/// The offline packages a test installs: the origin and limits its device files run under, and
/// the archives it serves -- every archive address the app fetches is answered from [serve]d
/// bytes alone, and recorded in [fetched]. Nothing leaves the process.
class CruftFreeTestPackages {
  CruftFreeTestPackages({required this.origin, this.limits = packageLimits});

  final Uri origin;
  final PackageLimits limits;
