  /// Serves [bytes] at [address].
  void serve(String address, Uint8List bytes) {
    _served[address] = bytes;
  }

  Future<Uint8List?> _fetch(String address) async {
    fetched.add(address);
    return _served[address];
  }

  DeviceFiles _files(DeviceStore store) => DeviceFiles(store, origin, fetch: _fetch, limits: limits);
}

