/// A session holding only roles: tokens never materialize.
class _TestSession extends Session {
  _TestSession(this._appStrings) : _testLocale = _appStrings.defaultLocale, super(_appStrings);

  final AppStrings _appStrings;
  final List<Future<void> Function()> _logoutHooks = [];
  final List<Future<void> Function()> _endHooks = [];
  List<String>? _roles;
  String _testLocale;

  void signIn(List<String> roles) {
    _roles = List.unmodifiable(roles);
    notifyListeners();
  }

  @override
  Future<void> init(NativeClientIdentity? identity) async {}

  @override
  void registerLoginHook(Future<void> Function() hook) {}

  @override
  void registerLogoutHook(Future<void> Function() hook) {
    _logoutHooks.add(hook);
  }

  @override
  void registerSessionEndHook(Future<void> Function() hook) {
    _endHooks.add(hook);
  }

  @override
  bool get holdsSession => _roles != null;

  @override
  bool get isAuthenticated => _roles != null;

  @override
  Future<String?> accessToken() async => null;

  @override
  bool hasRole(String role) => _roles?.contains(role) ?? false;

  @override
  String claim(String name) => throw UnauthorizedError("Session.claim('$name') read in a test session, which carries roles only.");

  @override
  Future<void> login() async {
    throw StateError('A test session never runs a hosted login; sign in with signIn([...]).');
  }

  @override
  Future<void> logout() async {
    for (final hook in [..._logoutHooks]) {
      await hook();
    }
    _roles = null;
    for (final hook in [..._endHooks]) {
      await hook();
    }
    notifyListeners();
  }

  @override
  String get locale => _testLocale;

  @override
  List<String> get locales => _appStrings.locales;

  @override
  Future<void> setLocale(String code) async {
    if (!_appStrings.locales.contains(code)) {
      throw ValidationError("Unsupported locale '$code'; expected one of: ${_appStrings.locales.join(', ')}");
    }
    _testLocale = code;
    notifyListeners();
  }
}

