  const _Answer.error(Object this.error) : value = null;

  final Object? value;
  final Object? error;
}

/// Answers every call of the app's API clients from the test; nothing
/// reaches the network.
class _TestTransport extends ApiTransport {
  _TestTransport(this._harness) : super(_testConfig.apiBaseUrl, MockClient((request) async => throw StateError('A UI test never reaches the network.')));

  final _Harness _harness;

  @override
  Future<Object?> send(String method, String path, {Map<String, Object?> query = const {}, Object? jsonBody, bool hasBody = false, bool bytesAnswer = false, required String accept}) {
    return _harness.dispatch(_harness.call(method, path, query, hasBody ? jsonBody : null));
  }

  @override
  Future<Object?> sendMultipart(String method, String path, {Map<String, Object?> query = const {}, required Map<String, String?> fields, required Map<String, UploadFile?> files, bool bytesAnswer = false, required String accept}) {
    final parts = <String, Object?>{
      ...fields,
      for (final entry in files.entries)
        if (entry.value != null) entry.key: entry.value!.filename,
    };
    return _harness.dispatch(_harness.call(method, path, query, parts));
  }
}

String _canonical(Object? value) {
  if (value is Map) {
    final keys = value.keys.map((key) => '$key').toList()..sort();
    return '{${keys.map((key) => '${jsonEncode(key)}:${_canonical(value[key])}').join(',')}}';
  }
  if (value is List) {
    return '[${value.map(_canonical).join(',')}]';
  }
  return jsonEncode(value);
}

class _Harness {
  _Harness(this.tester, this.app);

  final WidgetTester tester;
  final CruftFreeTestApp app;
  late final CruftFreeRuntime runtime;
  late final _TestSession session;
  final Map<String, _Answer> _answers = {};
  final List<String> _calls = [];
  final List<String> _failures = [];
  final List<bool> _confirmAnswers = [];
  bool _capturing = false;
  String? _captured;
  bool _mounted = false;

  _Call call(String method, String path, Map<String, Object?> query, Object? body) {
    final position = app.pagePosition;
    final named = {
      for (final entry in query.entries)
        if (entry.key != position && entry.value != null) entry.key: entry.value,
    };
    return _Call('$method $path ${_canonical(named)} ${_canonical(jsonDecode(jsonEncode(body)))}', position == null ? null : query[position]);
  }

  Future<Object?> dispatch(_Call call) {
    if (_capturing) {
      _captured = call.key;
      return Completer<Object?>().future;
    }
    _calls.add(call.key);
    final answer = _answers[call.key];
    if (answer == null) {
      final failure = 'Unanswered call ${call.key}: the test never answered it with respond(...) or respondError(...).';
      _failures.add(failure);
      return Future<Object?>.error(CruftFreeException(failure));
    }
    final error = answer.error;
    if (error != null) {
      return Future<Object?>.error(error);
    }
    final position = call.position;
    return Future<Object?>.value(position == null ? answer.value : _pageAt(answer.value, int.parse('$position')));
  }

  /// The envelope a paginated route answers for [position]: the rows the test answered are the
  /// first page, every later position is empty, and the total is always their count.
  Map<String, Object?> _pageAt(Object? rows, int position) {
    if (rows is! List<Object?>) {
      throw StateError('A paginated call is answered with the list of rows its first page shows.');
    }
    final limit = rows.isEmpty ? 1 : rows.length;
    final offset = app.pageAdvance == PositionAdvance.pageIndex ? position * limit : position;
    return {'items': offset == 0 ? rows : const <Object?>[], 'total': rows.length, 'offset': offset, 'limit': limit};
  }

  String capture(Future<Object?> Function() call) {
    _capturing = true;
    _captured = null;
    try {
      unawaited(call());
    } finally {
      _capturing = false;
    }
    final captured = _captured;
    if (captured == null) {
      throw ArgumentError('respond/respondError/called names no call of the app\'s API clients.');
    }
    return captured;
  }

  bool made(String key) => _calls.contains(key);

  void answer(String key, _Answer answer) {
    _answers[key] = answer;
  }

  void queueConfirm(bool answer) {
    _confirmAnswers.add(answer);
  }

  Future<void> mount(CruftFreeMount target, Map<String, Object?> args) async {
    switch (target) {
      case CruftFreeRoute(:final pathTemplate):
        runtime.router.go(runtime.nav.url(pathTemplate, args));
        if (!_mounted) {
          await tester.pumpWidget(CruftFreeApp(runtime: runtime, theme: app.theme, darkTheme: app.darkTheme));
        }
      case CruftFreeWidget(:final widget):
        await tester.pumpWidget(
          MaterialApp(
            navigatorKey: runtime.navigatorKey,
            scaffoldMessengerKey: runtime.messengerKey,
            theme: app.theme,
            darkTheme: app.darkTheme,
            builder: (context, pages) => cruftfreePrintablePages(context, runtime, pages),
            home: Scaffold(body: SingleChildScrollView(child: widget)),
          ),
        );
    }
    _mounted = target is CruftFreeRoute;
    await settle();
  }

  /// Pumps until the app is idle, answering every confirm dialog it shows
  /// from the queued answers.
  Future<void> settle() async {
    await tester.pumpAndSettle();
    while (await _answerConfirm()) {
      await tester.pumpAndSettle();
    }
  }

  Future<bool> _answerConfirm() async {
    final confirmText = runtime.messages.key('framework.confirm').text;
    final cancelText = runtime.messages.key('framework.cancel').text;
    Finder button(String text) => find.descendant(of: find.byType(AlertDialog), matching: find.widgetWithText(TextButton, text));
    if (button(confirmText).evaluate().isEmpty) {
      return false;
    }
    if (_confirmAnswers.isEmpty) {
      throw TestFailure('Ui.confirm(...) was shown but the test queued no answer with answerConfirm(...).');
    }
    await tester.tap(button(_confirmAnswers.removeAt(0) ? confirmText : cancelText));
    return true;
  }

  void finish() {
    if (_failures.isNotEmpty) {
      throw TestFailure(_failures.join('\n'));
    }
  }
}

_Harness? _current;

_Harness get _harness {
  final harness = _current;
  if (harness == null) {
    throw StateError('No app is under test; the test starts with cruftfreeStartUiTest(tester, appUnderTest).');
  }
  return harness;
}

/// Starts one test of [app]: a fresh role-only session, persisted state over
/// an in-memory store, a device store in a directory of the test's own, and a
/// runtime whose every call the test answers -- and whose archive downloads [packages] serves
/// (none: every download is refused).
Future<void> cruftfreeStartUiTest(WidgetTester tester, CruftFreeTestApp app, {CruftFreeTestPackages? packages}) async {
  SharedPreferencesAsyncPlatform.instance = InMemorySharedPreferencesAsync.empty();
  final harness = _Harness(tester, app);
  final strings = await tester.runAsync(() => AppStrings.load(app.stringsAsset));
  if (strings == null) {
    throw StateError('The strings catalog ${app.stringsAsset} did not load.');
  }
  final session = _TestSession(strings);
  final persisted = await tester.runAsync(() => PersistedState.load(strings.appKey, session));
  if (persisted == null) {
    throw StateError('The persisted state of ${strings.appKey} did not load.');
  }
  final storeRoot = await tester.runAsync(() => Directory.systemTemp.createTemp('cruftfree_store'));
  final store = storeRoot == null ? null : await tester.runAsync(() => DeviceStore.openIn(storeRoot, strings.appKey, session, signsIn: false));
  if (storeRoot == null || store == null) {
    throw StateError('The device store of ${strings.appKey} did not open.');
  }
  final navigatorKey = GlobalKey<NavigatorState>();
  harness.session = session;
  final files = packages?._files(store) ?? DeviceFiles(store, null, fetch: _noArchive);
  harness.runtime = CruftFreeRuntime(config: _testConfig, session: session, strings: strings, router: app.buildRouter(navigatorKey, session), navigatorKey: navigatorKey, persisted: persisted, store: store, link: const UnlinkedDevice(), transport: _TestTransport(harness), files: files);
  installCruftFreeRuntime(harness.runtime);
  _current = harness;
  addTearDown(() async {
    _current = null;
    // Unmounting disposes every owner, which cancels the delayed and repeating actions it
    // scheduled: a test ends with no timer pending.
    await tester.pumpWidget(const SizedBox.shrink());
    harness.finish();
    await tester.runAsync(() => storeRoot.delete(recursive: true));
  });
}

/// The mounted app, as a test drives it.
class CruftFreeScreen {
  const CruftFreeScreen._(this._h);

  final _Harness _h;

  Future<void> tap(String kind, Object? name) async {
    // A browser click does not depend on the viewport, so the element is scrolled into view first:
    // a tap below the test viewport would otherwise miss and only warn.
    final target = _one(kind, name);
    await _h.tester.ensureVisible(target);
    await _h.tester.pump();
    await _h.tester.tap(target);
    await _h.settle();
  }

  Future<void> enter(String kind, Object? name, Object? value) async {
    final field = find.descendant(of: _one(kind, name), matching: find.byType(EditableText));
    await _h.tester.enterText(field, textOf(value));
    await _h.settle();
  }

  Future<void> select(String kind, Object? name, List<Object?> values) async {
    final element = _one(kind, name);
    if (kind == 'select') {
      await _h.tester.tap(element);
      await _h.settle();
      for (final value in values) {
        await _h.tester.tap(find.text(textOf(value)).last);
        await _h.settle();
      }
      return;
    }
    if (kind != 'multiSelect' && kind != 'radio') {
      throw ArgumentError.value(kind, 'kind', 'screen.select chooses in a select, a multiSelect or a radio group');
    }
    for (final value in values) {
      await _h.tester.tap(find.descendant(of: element, matching: find.text(textOf(value))));
      await _h.settle();
    }
  }

  bool shows(Object? text) => find.text(textOf(text), findRichText: true).evaluate().isNotEmpty;

  Finder _one(String kind, Object? name) {
    final matches = _kinds[kind];
    if (matches == null) {
      throw ArgumentError.value(kind, 'kind', 'Not an element a test can find by its label');
    }
    final label = textOf(name);
    final finder = find.byWidgetPredicate((widget) => matches(widget, label), description: '$kind "$label"');
    final count = finder.evaluate().length;
    if (count != 1) {
      throw TestFailure('screen: expected exactly one $kind labelled "$label", found $count.');
    }
    return finder;
  }
}

/// Each findable element kind, and how a widget is that kind with that label.
final Map<String, bool Function(Widget widget, String label)> _kinds = {
  'button': (widget, label) => widget is CruftFreeButton && widget.label == label,
  'iconButton': (widget, label) => widget is CruftFreeIconButton && widget.label == label,
  'link': (widget, label) => widget is CruftFreeLink && widget.label == label,
  'menuItem': (widget, label) => widget is CruftFreeMenuItem && widget.label == label,
  'tab': (widget, label) => widget is Tab && widget.text == label,
  'input': (widget, label) => widget is CruftFreeTextInput && (widget.kind == CruftFreeTextKind.text || widget.kind == CruftFreeTextKind.secret) && widget.label == label,
  'textArea': (widget, label) => widget is CruftFreeTextInput && widget.kind == CruftFreeTextKind.multiline && widget.label == label,
  'search': (widget, label) => widget is CruftFreeTextInput && widget.kind == CruftFreeTextKind.search && widget.label == label,
  'number': (widget, label) => widget is CruftFreeNumberInput && widget.label == label,
  'select': (widget, label) => widget is CruftFreeSelect && widget.label == label,
  'multiSelect': (widget, label) => widget is CruftFreeMultiSelect && widget.label == label,
  'checkbox': (widget, label) => widget is CruftFreeCheck && !widget.toggle && widget.label == label,
  'toggle': (widget, label) => widget is CruftFreeCheck && widget.toggle && widget.label == label,
  'radio': (widget, label) => widget is CruftFreeRadioGroup && widget.label == label,
  'slider': (widget, label) => widget is CruftFreeSlider && widget.label == label,
};

/// `render(Page, args...)` / `render(Component, ...)`.
Future<CruftFreeScreen> cruftfreeRenderScreen(CruftFreeMount target, [Map<String, Object?> args = const {}]) async {
  final harness = _harness;
  await harness.mount(target, args);
  return CruftFreeScreen._(harness);
}

/// `navigated(Page, args...)`: whether the app shows that page's route.
bool cruftfreeUiTestNavigated(String pathTemplate, [Map<String, Object?> args = const {}]) {
  final runtime = _harness.runtime;
  return runtime.router.routerDelegate.currentConfiguration.uri.path == runtime.nav.url(pathTemplate, args);
}

/// `respond(call, value)`: [call] is answered with [value], as the backend
/// would send it.
void cruftfreeUiTestRespond(Future<Object?> Function() call, Object? value) {
  final harness = _harness;
  harness.answer(harness.capture(call), _Answer.value(jsonDecode(jsonEncode(value))));
}

/// `respondError(call, exception)`: [call] fails with [error].
void cruftfreeUiTestRespondError(Future<Object?> Function() call, Object error) {
  final harness = _harness;
  harness.answer(harness.capture(call), _Answer.error(error));
}

/// `called(call)`: whether the app made [call] with those arguments.
bool cruftfreeUiTestCalled(Future<Object?> Function() call) {
  final harness = _harness;
  return harness.made(harness.capture(call));
}

/// `sample(Type, member: value)`: the generator already built the value.
T cruftfreeUiTestSample<T>(T value) => value;

/// `signIn(roles)`: a session holding exactly [roles].
Future<void> cruftfreeUiTestSignIn(List<String> roles) async {
  final harness = _harness;
  harness.session.signIn(roles);
  await harness.settle();
}

/// `signOut()`: the session ends, running every logout and session-end hook.
Future<void> cruftfreeUiTestSignOut() async {
  final harness = _harness;
  await harness.session.logout();
  await harness.settle();
}

/// `answerConfirm(answer)`: what the next `Ui.confirm` receives.
void cruftfreeUiTestAnswerConfirm(bool answer) {
  _harness.queueConfirm(answer);
}

/// `setOnline(online)`: the device reports its network lost or found, as the
/// platform reports it, and `Device.isOnline` follows through the runtime's own
/// connectivity rule. A test app has no API origin to probe, so the network alone decides.
Future<void> cruftfreeUiTestSetOnline(bool online) async {
  final harness = _harness;
  harness.runtime.connectivity.observe(online ? ConnectivityEvent.networkFound : ConnectivityEvent.networkLost);
  await harness.settle();
}

/// `elapse(milliseconds)`: [milliseconds] pass on the test's clock, and every
/// delayed and repeating action due in them runs.
Future<void> cruftfreeUiTestElapse(int milliseconds) async {
  if (milliseconds < 1) {
    throw RangeError.range(milliseconds, 1, null, 'milliseconds', 'elapse lets at least one millisecond pass');
  }
  final harness = _harness;
  await harness.tester.pump(Duration(milliseconds: milliseconds));
  await harness.settle();
}
